/**
 * Axis-aligned rect used for measure-based zoom-to-cursor scroll correction.
 * @typedef {{ left: number, top: number, width: number, height: number }} ZoomFocalRect
 */

/**
 * @typedef {{ clientX: number, clientY: number, before: ZoomFocalRect }} ZoomFocalPending
 */

/**
 * Prefer the pointer when it sits on the content rect; otherwise zoom around its center.
 *
 * @param {ZoomFocalRect} canvas
 * @param {number} clientX
 * @param {number} clientY
 * @returns {{ clientX: number, clientY: number }}
 */
export function resolveZoomFocalPoint(canvas, clientX, clientY) {
  const inside =
    clientX >= canvas.left &&
    clientX <= canvas.left + canvas.width &&
    clientY >= canvas.top &&
    clientY <= canvas.top + canvas.height;
  if (inside) return { clientX, clientY };
  return {
    clientX: canvas.left + canvas.width / 2,
    clientY: canvas.top + canvas.height / 2,
  };
}

/**
 * Scroll deltas that keep the content point under (clientX, clientY) fixed after a zoom that
 * moved `before` → `after`. Apply with `scrollLeft += deltaLeft`, `scrollTop += deltaTop`.
 *
 * @param {ZoomFocalRect} before
 * @param {ZoomFocalRect} after
 * @param {number} clientX
 * @param {number} clientY
 * @returns {{ deltaLeft: number, deltaTop: number }}
 */
export function zoomFocalScrollDelta(before, after, clientX, clientY) {
  if (before.width <= 0 || before.height <= 0) return { deltaLeft: 0, deltaTop: 0 };
  const relX = clientX - before.left;
  const relY = clientY - before.top;
  const newScreenX = after.left + relX * (after.width / before.width);
  const newScreenY = after.top + relY * (after.height / before.height);
  return {
    deltaLeft: newScreenX - clientX,
    deltaTop: newScreenY - clientY,
  };
}

/**
 * @param {DOMRectReadOnly | ZoomFocalRect} rect
 * @returns {ZoomFocalRect}
 */
export function snapshotZoomFocalRect(rect) {
  return { left: rect.left, top: rect.top, width: rect.width, height: rect.height };
}

/**
 * Choose which rect the focal correction should anchor on.
 *
 * Anchoring on the whole page stack is wrong: its height is *affine* in zoom, not
 * proportional. Every section contributes a header and spacer that stay a fixed pixel size,
 * so the stack measures `H(z) = naturalTotal * z + chromeTotal`. `zoomFocalScrollDelta` maps a
 * point by the ratio of before/after heights, which only holds for a uniformly scaled box —
 * against the stack it drifts by the accumulated chrome (measured: ~64px going 122% → 200%,
 * and worse the deeper the target sits).
 *
 * An individual sheet *is* uniformly scaled (`transform: scale()`), so anchoring on the sheet
 * under the pointer makes the mapping exact. Falls back to the nearest sheet when the pointer
 * sits in the gutter between them.
 *
 * @param {ZoomFocalRect[]} rects
 * @param {number} clientX
 * @param {number} clientY
 * @returns {number} index into `rects`, or -1 when there is nothing to anchor on
 */
export function pickZoomFocalAnchor(rects, clientX, clientY) {
  let nearest = -1;
  let nearestDistance = Infinity;
  for (let index = 0; index < rects.length; index += 1) {
    const rect = rects[index];
    if (rect.width <= 0 || rect.height <= 0) continue;
    const inside =
      clientX >= rect.left &&
      clientX <= rect.left + rect.width &&
      clientY >= rect.top &&
      clientY <= rect.top + rect.height;
    if (inside) return index;
    const dx = clientX - (rect.left + rect.width / 2);
    const dy = clientY - (rect.top + rect.height / 2);
    const distance = dx * dx + dy * dy;
    if (distance < nearestDistance) {
      nearestDistance = distance;
      nearest = index;
    }
  }
  return nearest;
}

/**
 * Whether a computed `overflow-x` / `overflow-y` value declares a scroll container.
 *
 * Keyed off the *declared* value rather than `scrollHeight > clientHeight`: an element that
 * is not scrollable yet still becomes the scroller once zoom grows the content, so probing
 * current scrollability picks the wrong element and the focal correction lands nowhere.
 *
 * @param {string} value
 * @returns {boolean}
 */
export function isScrollableOverflow(value) {
  return value === 'auto' || value === 'scroll' || value === 'overlay';
}
